# Builds lib/import/us-local-popular.ts from the owner's Leads_categories.xlsx (usage: python3 build_popular.py <xlsx>)
import openpyxl,re,json,sys
wb=openpyxl.load_workbook(sys.argv[1],read_only=True)
rows=[r[0] for r in list(wb['categories'].iter_rows(values_only=True))[1:] if r[0]]
deny=re.compile(r"\b(bus stop|bus station|atm|building|park|parking|river|lake|mountain|ravine|spring|natural feature|historical|landmark|postal code|cemetery|church|churches|synagogue|mosque|temple|religious|place of worship|ministry|school|schools|university|college|library|police|fire station|government|city hall|courthouse|post office|airport|playground|field|stadium|trail|hiking|tourist|museum|housing|apartment building|apartment complex|condominium|complex|neighborhood|community|non-profit|association|organization|foundation|charity|food bank|utility|water|electric vehicle|charging|transit|transport interchange|boat ramp|beach|island|bridge|dam|forest|farm|ranch|cannabis|vaporizer|tobacco|gun shop|firearm|adult|casino|bail|pawn|military|army|navy|embassy|consulate|district|department|office of|county|state|federal|municipal|public|senior center|veterans|fraternal|cooperative|credit union|bank|corporate office|business center|geographic|region|area|monument|memorial|reservoir|canal|harbor|port|marina|ferry|train station|subway|railway|highway|road|street|intersection|crossing|rest area|scenic|overlook|picnic|lookout|shelter|camp|wildlife|nature reserve|conservation|sanctuary|zoo|aquarium|cinema|waterfall|arena|haunted|blood|visa|offices?|markets?|ponds?|piers?|bays?|ridges?|wetlands?|cliffs?|caves?|valleys?|hills?|creeks?|streams?|swamps?)\b|\(|/",re.I)
src=open('lib/import/us-local-types.ts').read()
exist=re.findall(r'"([^"]+)"',src.split('export const allUsTypes')[0])
norm=lambda s:re.sub(r'[^a-z]','',s.lower()).rstrip('s')
existing={norm(e) for e in exist}
generic={'stores','shops','companies','services','contractors','consultants','manufacturers','homehelps','wholesalers'}
def plural(w):
    parts=w.strip().split(' ');last=parts[-1]
    if last.endswith('s') and not last.endswith('ss'): p=last
    elif re.search(r'(s|x|z|ch|sh)$',last): p=last+'es'
    elif re.search(r'[^aeiou]y$',last): p=last[:-1]+'ies'
    else: p=last+'s'
    parts[-1]=p;return ' '.join(parts)
small={'and','of','the','in','for','to','or','a'}
title=lambda s:' '.join(w if (w in small and i) else w[:1].upper()+w[1:] for i,w in enumerate(s.split(' ')))
out=[];seen=set()
for n in rows:
    if deny.search(n): continue
    t=title(plural(n.replace(' & ',' and ')));k=norm(t)
    if k in existing or k in seen or k in generic or 'helps' in k: continue
    seen.add(k);out.append(t)
    if len(out)==1000:break
open('lib/import/us-local-popular.ts','w').write("// Most popular US local-business categories from the owner's Leads_categories.xlsx (21 Nov 2026), ranked by the sheet's appearance count.\n// Generated by scripts/us-local/build_popular.py. Non-business places and types already in us-local-types.ts are left out.\nexport const POPULAR_US_TYPES: string[] = "+json.dumps(out,indent=0)+";\n")
print(len(out))
